              if (note.children.length &gt; 0 && note.children[0].tagName === "HEADER") {
                note.children[0].remove();
              }
              const html = processXRef(null, note);
              instance.setContent(html);
            } 
          }).finally(() =&gt; {
            instance.enable();
            instance.show();
          });
        }
